CREATE OR REPLACE FUNCTION public.pm_guard_row() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_TABLE_NAME='pm_projects' THEN IF TG_OP='UPDATE' THEN IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.manager_id IS DISTINCT FROM OLD.manager_id THEN RAISE EXCEPTION 'Identidade e gestor do projeto são preservados'; END IF; END IF; NEW.updated_at:=now(); RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN RAISE EXCEPTION 'Não é permitido mover registros entre projetos'; END IF; END IF;
 IF EXISTS(SELECT 1 FROM public.pm_projects WHERE id=NEW.project_id AND status IN ('concluido','cancelado')) THEN RAISE EXCEPTION 'Projeto encerrado não pode ser alterado'; END IF;
 IF TG_TABLE_NAME='pm_tasks' THEN IF NEW.phase_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.pm_phases WHERE id=NEW.phase_id AND project_id=NEW.project_id) THEN RAISE EXCEPTION 'Fase de outro projeto'; END IF; END IF; IF NEW.responsible_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.pm_projects WHERE id=NEW.project_id AND manager_id=NEW.responsible_id) AND NOT EXISTS(SELECT 1 FROM public.pm_members WHERE project_id=NEW.project_id AND user_id=NEW.responsible_id) THEN RAISE EXCEPTION 'Responsável não pertence à equipe'; END IF; END IF; END IF;
 IF TG_TABLE_NAME='pm_allocations' THEN IF NOT EXISTS(SELECT 1 FROM public.pm_tasks WHERE id=NEW.task_id AND project_id=NEW.project_id) OR NOT EXISTS(SELECT 1 FROM public.pm_resources WHERE id=NEW.resource_id AND project_id=NEW.project_id) THEN RAISE EXCEPTION 'Alocação de outro projeto'; END IF; END IF;
 RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.pm_guard_closed() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p uuid; s text; BEGIN
 IF TG_TABLE_NAME='pm_projects' THEN p:=OLD.id; ELSE p:=COALESCE(NEW.project_id,OLD.project_id); END IF; SELECT status INTO s FROM public.pm_projects WHERE id=p;
 IF TG_TABLE_NAME='pm_projects' THEN IF TG_OP='UPDATE' THEN IF OLD.status IN ('concluido','cancelado') THEN RAISE EXCEPTION 'Projeto encerrado não pode ser alterado'; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NOT public.pm_can_manage(OLD.id) THEN RAISE EXCEPTION 'Somente gestores alteram a situação'; END IF; END IF; ELSE IF s IN ('concluido','cancelado') THEN RAISE EXCEPTION 'Projeto encerrado não pode ser alterado'; END IF; END IF;
 IF TG_TABLE_NAME='pm_tasks' THEN IF TG_OP<>'DELETE' THEN IF NEW.milestone AND NEW.duration<>0 OR NOT NEW.milestone AND NEW.duration<1 THEN RAISE EXCEPTION 'Marcos têm duração zero e atividades têm duração positiva'; END IF; END IF; END IF;
 IF TG_TABLE_NAME='pm_allocations' THEN IF TG_OP='UPDATE' THEN IF NEW.task_id IS DISTINCT FROM OLD.task_id OR NEW.resource_id IS DISTINCT FROM OLD.resource_id OR NEW.unit_rate IS DISTINCT FROM OLD.unit_rate THEN RAISE EXCEPTION 'A tarefa, o recurso e a taxa registrada da alocação são preservados'; END IF; END IF; END IF;
 IF TG_TABLE_NAME='pm_phases' THEN IF TG_OP='UPDATE' THEN IF (NEW.accepted_at IS DISTINCT FROM OLD.accepted_at OR NEW.accepted_by IS DISTINCT FROM OLD.accepted_by) AND NOT public.pm_can_manage(NEW.project_id) THEN RAISE EXCEPTION 'Somente gestores aceitam entregáveis'; END IF; END IF; END IF;
 RETURN COALESCE(NEW,OLD); END $$;